ranhos \\u00e0 nossa intui\\u00e7\\u00e3o, s\\u00e3o fundamentais para tecnologias modernas como lasers, computadores, tomografias e a computa\\u00e7\\u00e3o qu\\u00e2ntica.<\\/p>\",\"typography_typography\":\"custom\",\"typography_font_family\":\"Montserrat\",\"typography_font_size\":{\"unit\":\"px\",\"size\":18,\"sizes\":[]},\"typography_font_weight\":\"700\",\"text_color\":\"#6EC1E4\",\"__globals__\":{\"typography_typography\":\"\",\"text_color\":\"globals\\/colors?id=primary\"}},\"elements\":[],\"widgetType\":\"text-editor\"},{\"id\":\"a6feab0\",\"elType\":\"widget\",\"settings\":{\"text\":\"Laborat\\u00f3rios\",\"icon_align\":\"row-reverse\",\"icon_indent\":{\"unit\":\"px\",\"size\":7,\"sizes\":[]},\"align\":\"left\",\"typography_typography\":\"custom\",\"typography_font_family\":\"Montserrat\",\"typography_font_size\":{\"unit\":\"px\",\"size\":16,\"sizes\":[]},\"typography_font_weight\":\"600\",\"text_shadow_text_shadow_type\":\"yes\",\"button_text_color\":\"#000000\",\"background_background\":\"gradient\",\"background_color\":\"#87CEEB\",\"background_color_b\":\"#003BB1\",\"hover_color\":\"#FAFCF9\",\"hover_animation\":\"shrink\",\"border_radius\":{\"unit\":\"px\",\"top\":\"5\",\"right\":\"5\",\"bottom\":\"5\",\"left\":\"5\",\"isLinked\":true},\"text_padding\":{\"unit\":\"px\",\"top\":\"12\",\"right\":\"12\",\"bottom\":\"12\",\"left\":\"12\",\"isLinked\":true},\"__globals__\":{\"typography_typography\":\"\",\"button_text_color\":\"\",\"background_color\":\"globals\\/colors?id=6ab7176\",\"background_color_b\":\"globals\\/colors?id=f70c870\"}},\"elements\":[],\"widgetType\":\"button\"}],\"isInner\":true}],\"isInner\":false},{\"id\":\"f09ad8b\",\"elType\":\"container\",\"settings\":{\"flex_direction\":\"column\",\"margin\":{\"unit\":\"px\",\"top\":\"100\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":false}},\"elements\":[{\"id\":\"5ecbb20\",\"elType\":\"widget\",\"settings\":{\"title\":\"DIRETOR\",\"align\":\"center\",\"typography_typography\":\"