;\\r\\n      dot.classList.add(\'carousel-dot\');\\r\\n      if (i === 0) dot.classList.add(\'active\');\\r\\n      dot.addEventListener(\'click\', () => goToSlide(i));\\r\\n      dotsNav.appendChild(dot);\\r\\n    });\\r\\n\\r\\n    const dots = Array.from(dotsNav.children);\\r\\n\\r\\n    function updateSlidePosition() {\\r\\n      track.style.transform = `translateX(-${currentIndex * 100}%)`;\\r\\n      dots.forEach(dot => dot.classList.remove(\'active\'));\\r\\n      dots[currentIndex].classList.add(\'active\');\\r\\n    }\\r\\n\\r\\n    function goToSlide(index) {\\r\\n      currentIndex = index;\\r\\n      updateSlidePosition();\\r\\n    }\\r\\n\\r\\n    function nextSlide() {\\r\\n      currentIndex = (currentIndex + 1) % slides.length;\\r\\n      updateSlidePosition();\\r\\n    }\\r\\n\\r\\n    function prevSlide() {\\r\\n      currentIndex = (currentIndex - 1 + slides.length) % slides.length;\\r\\n      updateSlidePosition();\\r\\n    }\\r\\n\\r\\n    nextButton.addEventListener(\'click\', nextSlide);\\r\\n    prevButton.addEventListener(\'click\', prevSlide);\\r\\n\\r\\n    \\/\\/ Auto play (opcional)\\r\\n    setInterval(nextSlide, 5000);\\r\\n  <\\/script>\\r\\n\\r\\n<\\/body>\\r\\n<\\/html>\\r\\n\"},\"elements\":[],\"widgetType\":\"html\"}],\"isInner\":false},{\"id\":\"653a035\",\"elType\":\"container\",\"settings\":{\"flex_direction\":\"column\"},\"elements\":[{\"id\":\"effc71e\",\"elType\":\"widget\",\"settings\":{\"title\":\"Eventos\",\"header_size\":\"h1\",\"align\":\"center\",\"typography_typography\":\"custom\",\"typography_font_family\":\"Montserrat\",\"typography_font_size\":{\"unit\":\"px\",\"size\":48,\"sizes\":[]},\"typography_font_weight\":\"bold\"},\"elements\":[],\"widgetType\":\"heading\"}],\"isInner\":false},{\"id\":\"e0a170a\",\"elType\":\"container\",\"settings\":{\"flex_direction\":\"row\",\"flex_gap\":{\"unit\":\"px\",\"size\":40,\"column\":\"40\",\"row\":\"0\"},\"margin\":{\"unit\":\"px\",\"top\":\"100\",\"right\":\"0\",\"bottom\":\