r\\n<head>\\r\\n  <meta charset=\\\"UTF-8\\\">\\r\\n  <meta name=\\\"viewport\\\" content=\\\"width=device-width, initial-scale=1.0\\\">\\r\\n  <title>Carrossel Responsivo<\\/title>\\r\\n  <style>\\r\\n    * {\\r\\n      box-sizing: border-box;\\r\\n      margin: 0;\\r\\n      padding: 0;\\r\\n    }\\r\\n\\r\\n    body {\\r\\n      background: #f4f4f4;\\r\\n      overflow-x: hidden;\\r\\n    }\\r\\n\\r\\n    .carousel-section {\\r\\n      width: 100%;\\r\\n      margin: 0;\\r\\n      padding-top: 30px;\\r\\n    }\\r\\n\\r\\n    \\/* \\u00c1rea do t\\u00edtulo *\\/\\r\\n    .carousel-header {\\r\\n      max-width: 1200px;\\r\\n      margin: 0 auto 20px auto;\\r\\n      padding: 0 20px;\\r\\n    }\\r\\n\\r\\n    .carousel-title {\\r\\n      color: #003BB1;\\r\\n      text-align: center;\\r\\n      margin: 0;\\r\\n      font-family: inherit;\\r\\n      font-size: 2.5rem;\\r\\n      font-weight: 700;\\r\\n      line-height: 1.2;\\r\\n    }\\r\\n\\r\\n    \\/* Carrossel full width *\\/\\r\\n    .carousel {\\r\\n      position: relative;\\r\\n      width: 100vw;\\r\\n      height: 500px;\\r\\n      overflow: hidden;\\r\\n      background: #000;\\r\\n\\r\\n      \\/* faz o carrossel sair do limite central e encostar nas laterais *\\/\\r\\n      margin-left: calc(50% - 50vw);\\r\\n      margin-right: calc(50% - 50vw);\\r\\n    }\\r\\n\\r\\n    .carousel-track {\\r\\n      display: flex;\\r\\n      transition: transform 0.5s ease-in-out;\\r\\n      height: 100%;\\r\\n    }\\r\\n\\r\\n    .carousel-slide {\\r\\n      min-width: 100%;\\r\\n      height: 100%;\\r\\n      background-size: cover;\\r\\n      background-position: center;\\r\\n      background-repeat: no-repeat;\\r\\n      position: relative;\\r\\n    }\\r\\n\\r\\n    .carousel-caption {\\r\\n      position: absolute;\\r\\n      left: 0;\\r\\n      bottom: 0;\\r\\n      width: 100%;\\r\\n      background: rgba(0, 0, 0, 0.65);\\r\\n      color: #fff;\\r\\n      padding: 20px 25px;\\r\\n    }\\r\\n\\r\\n    .carousel-caption h3 {\\r\\n      font-size: 1.4rem;\\r\\n      margin-bottom: 8px;\\r\\n    }\\r\\n\\r\\n    .carousel-caption p {\\r\\n      font-size: 1rem;\\r\\n      line-height: 1.5;\\r\\n    }\\r\\n\\r\\n    .carousel-button {\\r\\n      position: absolute;\\r\\n      top: 50%;\\r\\n      transform: translateY(-50%);\\r\\n      background: rgba(0,0,0,0.5);\\r\\n      border: none;\\r\\n      color: #fff;\\r\\n      font-size: 2rem;\\r\\n      padding: 0.5rem 1rem;\\r\\n      cursor: pointer;\\r\\n      border-radius: 50%;\\r\\n      z-index: 10;\\r\\n      transition: background 0.3s;\\r\\n    }\\r\\n\\r\\n    .carousel-button:hover {\\r\\n      background: rgba(0,0,0,0.8);\\r\\n    }\\r\\n\\r\\n    .carousel-button.prev {\\r\\n      left: 20px;\\r\\n    }\\r\\n\\r\\n    .carousel-button.next {\\r\\n      right: 20px;\\r\\n    }\\r\\n\\r\\n    .carousel-dots {\\r\\n      position: absolute;\\r\\n      bottom: 100px;\\r\\n      left: 50%;\\r\\n      transform: translateX(-50%);\\r\\n      display: flex;\\r\\n      gap: 10px;\\r\\n      z-index: 11;\\r\\n    }\\r\\n\\r\\n    .carousel-dot {\\r\\n      width: 12px;\\r\\n      height: 12px;\\r\\n      background: rgba(255,255,255,0.6);\\r\\n      border-radius: 50%;\\r\\n      cursor: pointer;\\r\\n      transition: all 0.3s;\\r\\n    }\\r\\n\\r\\n    .carousel-dot.active {\\r\\n      background: #0072CE;\\r\\n      transform: scale(1.3);\\r\\n    }\\r\\n\\r\\n    @media (max-width: 768px) {\\r\\n      .carousel-section {\\r\\n        padding-top: 20px;\\r\\n      }\\r\\n\\r\\n      .carousel-header {\\r\\n        padding: 0 15px;\\r\\n        margin-bottom: 15px;\\r\\n      }\\r\\n\\r\\n      .carousel-title {\\r\\n        font-size: 2rem;\\r\\n      }\\r\\n\\r\\n      .carousel {\\r\\n        height: 350px;\\r\\n      }\\r\\n\\r\\n      .carousel-caption {\\r\\n        padding: 15px 18px;\\r\\n      }\\r\\n\\r\\n      .carousel-caption h3 {\\r\\n        font-size: 1.1rem;\\r\\n      }\\r\\n\\r\\n      .carousel-caption p