r um texto informativo, uma manchete ou subt\\u00edtulo.<\\/p>\\r\\n          <\\/div>\\r\\n        <\\/div>\\r\\n\\r\\n      <\\/div>\\r\\n\\r\\n      <button class=\\\"carousel-button prev\\\" aria-label=\\\"Slide anterior\\\">&#10094;<\\/button>\\r\\n      <button class=\\\"carousel-button next\\\" aria-label=\\\"Pr\\u00f3ximo slide\\\">&#10095;<\\/button>\\r\\n\\r\\n      <div class=\\\"carousel-dots\\\"><\\/div>\\r\\n    <\\/div>\\r\\n  <\\/section>\\r\\n\\r\\n  <script>\\r\\n    const track = document.querySelector(\'.carousel-track\');\\r\\n    const slides = Array.from(track.children);\\r\\n    const nextButton = document.querySelector(\'.carousel-button.next\');\\r\\n    const prevButton = document.querySelector(\'.carousel-button.prev\');\\r\\n    const dotsNav = document.querySelector(\'.carousel-dots\');\\r\\n\\r\\n    let currentIndex = 0;\\r\\n    let autoPlay = setInterval(nextSlide, 5000);\\r\\n\\r\\n    slides.forEach((_, i) => {\\r\\n      const dot = document.createElement(\'div\');\\r\\n      dot.classList.add(\'carousel-dot\');\\r\\n\\r\\n      if (i === 0) {\\r\\n        dot.classList.add(\'active\');\\r\\n      }\\r\\n\\r\\n      dot.addEventListener(\'click\', () => {\\r\\n        goToSlide(i);\\r\\n        resetAutoPlay();\\r\\n      });\\r\\n\\r\\n      dotsNav.appendChild(dot);\\r\\n    });\\r\\n\\r\\n    const dots = Array.from(dotsNav.children);\\r\\n\\r\\n    function updateSlidePosition() {\\r\\n      track.style.transform = `translateX(-${currentIndex * 100}%)`;\\r\\n      dots.forEach(dot => dot.classList.remove(\'active\'));\\r\\n      dots[currentIndex].classList.add(\'active\');\\r\\n    }\\r\\n\\r\\n    function goToSlide(index) {\\r\\n      currentIndex = index;\\r\\n      updateSlidePosition();\\r\\n    }\\r\\n\\r\\n    function nextSlide() {\\r\\n      currentIndex = (currentIndex + 1) % slides.length;\\r\\n      updateSlidePosition();\\r\\n    }\\r\\n\\r\\n    function prevSlide() {\\r\\n      currentIndex = (currentIndex - 1 + slides.length) % slides.length;\\r\\n      updateSlidePosition();\\r\\n    }\\r\\n\\r\\n    function resetAutoPlay() {\\r\\n      clearInterval(autoPlay);\\r\\n      autoPlay = setInterval(nextSlide, 5000);\\r\\n    }\\r\\n\\r\\n    nextButton.addEventListener(\'click\', () => {\\r\\n      nextSlide();\\r\\n      resetAutoPlay();\\r\\n    });\\r\\n\\r\\n    prevButton.addEventListener(\'click\', () => {\\r\\n      prevSlide();\\r\\n      resetAutoPlay();\\r\\n    });\\r\\n  <\\/script>\\r\\n\\r\\n<\\/body>\\r\\n<\\/html>\"},\"elements\":[],\"widgetType\":\"html\"}],\"isInner\":false},{\"id\":\"653a035\",\"elType\":\"container\",\"settings\":{\"flex_direction\":\"column\",\"background_background\":\"gradient\",\"background_color_b\":\"\",\"__globals__\":{\"background_color\":\"globals\\/colors?id=41c3483\"},\"margin\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":false},\"padding\":{\"unit\":\"px\",\"top\":\"100\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":false},\"_flex_align_self\":\"center\"},\"elements\":[{\"id\":\"effc71e\",\"elType\":\"widget\",\"settings\":{\"title\":\"Eventos\",\"header_size\":\"h1\",\"align\":\"center\",\"typography_typography\":\"custom\",\"typography_font_family\":\"Montserrat\",\"typography_font_size\":{\"unit\":\"px\",\"size\":45,\"sizes\":[]},\"typography_font_weight\":\"bold\",\"text_shadow_text_shadow\":{\"horizontal\":7,\"vertical\":11,\"blur\":11,\"color\":\"rgba(0,0,0,0.3)\"},\"__globals__\":{\"typography_typography\":\"\",\"title_color\":\"\"},\"title_color\":\"#003BB1\"},\"elements\":[],\"widgetType\":\"heading\"}],\"isInner\":false},{\"id\":\"e0a170a\",\"elType\":\"container\",\"settings\":{\"flex_direction\":\"row\",\"flex_gap\":{\"unit\":\"px\",\"size\":40,\"column\":\"40\",\"row\":\"0\"},\"margin\":{\"unit\":\"px\",\"top\":\"40\",\"right\":\"0\",\"bottom\":\"100\",\"left\":\"0\",\"isLinked\":false},\"background_background\":\"classic\",\"__globals__\":{\"backg