on: center;\\r\\n      background-repeat: no-repeat;\\r\\n      position: relative;\\r\\n    }\\r\\n\\r\\n    .carousel-caption {\\r\\n      position: absolute;\\r\\n      left: 0;\\r\\n      bottom: 0;\\r\\n      width: 100%;\\r\\n      background: rgba(0, 0, 0, 0.65);\\r\\n      color: #fff;\\r\\n      padding: 20px 25px;\\r\\n    }\\r\\n\\r\\n    .carousel-caption h3 {\\r\\n      font-size: 1.4rem;\\r\\n      margin-bottom: 8px;\\r\\n    }\\r\\n\\r\\n    .carousel-caption p {\\r\\n      font-size: 1rem;\\r\\n      line-height: 1.5;\\r\\n    }\\r\\n\\r\\n    .carousel-button {\\r\\n      position: absolute;\\r\\n      top: 50%;\\r\\n      transform: translateY(-50%);\\r\\n      background: rgba(0,0,0,0.5);\\r\\n      border: none;\\r\\n      color: #fff;\\r\\n      font-size: 2rem;\\r\\n      padding: 0.5rem 1rem;\\r\\n      cursor: pointer;\\r\\n      border-radius: 50%;\\r\\n      z-index: 10;\\r\\n      transition: background 0.3s;\\r\\n    }\\r\\n\\r\\n    .carousel-button:hover {\\r\\n      background: rgba(0,0,0,0.8);\\r\\n    }\\r\\n\\r\\n    .carousel-button.prev {\\r\\n      left: 20px;\\r\\n    }\\r\\n\\r\\n    .carousel-button.next {\\r\\n      right: 20px;\\r\\n    }\\r\\n\\r\\n    .carousel-dots {\\r\\n      position: absolute;\\r\\n      bottom: 100px;\\r\\n      left: 50%;\\r\\n      transform: translateX(-50%);\\r\\n      display: flex;\\r\\n      gap: 10px;\\r\\n      z-index: 11;\\r\\n    }\\r\\n\\r\\n    .carousel-dot {\\r\\n      width: 12px;\\r\\n      height: 12px;\\r\\n      background: rgba(255,255,255,0.6);\\r\\n      border-radius: 50%;\\r\\n      cursor: pointer;\\r\\n      transition: all 0.3s;\\r\\n    }\\r\\n\\r\\n    .carousel-dot.active {\\r\\n      background: #0072CE;\\r\\n      transform: scale(1.3);\\r\\n    }\\r\\n\\r\\n    @media (max-width: 768px) {\\r\\n      .carousel-section {\\r\\n        padding-top: 20px;\\r\\n      }\\r\\n\\r\\n      .carousel-header {\\r\\n        padding: 0 15px;\\r\\n        margin-bottom: 15px;\\r\