ursor: pointer;\n      border-radius: 50%;\n      z-index: 10;\n      transition: background 0.3s;\n    }\n    .carousel-button:hover {\n      background: rgba(0,0,0,0.8);\n    }\n    .carousel-button.prev { left: 20px; }\n    .carousel-button.next { right: 20px; }\n    /* 🔹 Bolinhas indicadores */\n    .carousel-dots {\n      position: absolute;\n      bottom: 15px;\n      left: 50%;\n      transform: translateX(-50%);\n      display: flex;\n      gap: 10px;\n    }\n    .carousel-dot {\n      width: 12px;\n      height: 12px;\n      background: rgba(255,255,255,0.6);\n      border-radius: 50%;\n      cursor: pointer;\n      transition: all 0.3s;\n    }\n    .carousel-dot.active {\n      background: #0072CE;\n      transform: scale(1.3); /* 🔹 Bolinha ativa maior */\n    }\n  \n\n\n    <!-- Botões -->\n    <button>&#10094;</button>\n    <button>&#10095;</button>\n    <!-- Bolinhas -->\n\n\n					<h1>Eventos</h1>																<a href=\"http://localhost/fisica/wp-content/uploads/2025/09/WhatsApp-Image-2025-08-25-at-15.23.48.jpg\">\n							<img width=\"800\" height=\"800\" src=\"http://localhost/fisica/wp-content/uploads/2025/09/WhatsApp-Image-2025-08-25-at-15.23.48.jpg\" alt=\"\" />								</a>\n																											<a href=\"http://localhost/fisica/wp-content/uploads/2025/09/WhatsApp-Image-2025-08-25-at-15.22.50.jpg\">\n							<img width=\"800\" height=\"800\" src=\"http://localhost/fisica/wp-content/uploads/2025/09/WhatsApp-Image-2025-08-25-at-15.22.50.jpg\" alt=\"\" />								</a>\n																											<a href=\"http://localhost/fisica/wp-content/uploads/2026/04/PHOTO-2026-03-18-16-03-28.jpg\">\n							<img width=\"800\" height=\"800\" src=\"http://localhost/fisica/wp-content/uploads/2026/04/PHOTO-2026-03-18-16-03-28.jpg\" alt=\"\" />								</a>\n																<h1>Conheça Nossos Laboratórios</h1>		[icones_servicos_uerj]			<h1>Pesquisa e Desenvolvimento</h1>		[quadrados_servicos_link]','O Instituto','','inherit','closed','closed','','9-revision-v1',''